
import type { MoneyValue } from './MoneyValue.js';
import type { OrderPaymentIntentSelection } from './OrderPaymentIntentSelection.js';

export type PayOrderRequestConfirmPaymentIntents = { "action": "confirm_payment_intents" | (string & {}); /** Buyer email for receipts and the order's buyer_email. A checkout session credential that omits it uses the email saved on the session's buyer_contact. */ "buyer_email"?: string; /** Buyer phone in E.164 format, recorded as the order's buyer_phone. A checkout session credential that omits it uses the phone saved on the session's buyer_contact. */ "buyer_phone"?: string; "completion_behavior"?: "complete_order" | "partial_payment" | (string & {}); "expected_outstanding_money"?: MoneyValue; /** minItems: 1. */ "payment_intents": Array<OrderPaymentIntentSelection>; /** The buyer's choice to save the card they typed for faster checkout at this merchant. Send true only from the checkout session's own credential, when the session's save_payment_method_offered is true and save_payment_method_requires_verification is false, for one newly collected card sent as a confirmation_token created with setup_future_usage on_session. The card is saved with usage on_session once the payment succeeds, for the customer the checkout acts for: the customer the merchant created the session for, or the customer whose email the buyer confirmed in it. A typed buyer_email never decides it. A checkout that acts for no customer refuses the save until the buyer confirms their email with a code, unless it sends save_payment_method_phone. A checkout the buyer bound by a texted code saves the card with that number. A checkout whose buyer confirmed the customer's email can also send save_payment_method_phone, to save the card with a number the buyer confirms by text after paying. Send false or omit it when the buyer does not choose to save; the confirmation_token must then have no setup_future_usage. */ "save_payment_method"?: boolean; /** A US or Canadian mobile phone number in E.164 format, such as +14155552671, that confirms a card saved while the checkout acts for no customer, or for the customer whose email the buyer confirmed in it. Send it with save_payment_method: true only from the checkout session's own credential, when the session's save_payment_method_phone_offered is true. The card is kept for the customer the checkout acts for, or else the merchant's customer with the buyer's email, once the payment succeeds, or once it is approved when the merchant captures later, but works for nothing until the buyer confirms it within 24 hours, with a code texted to this number or, when the customer's email is the email of the payment, emailed there instead: request the code with POST /v1/checkout-sessions/{checkout_session_id}/customer-verifications and purpose confirm_saved_payment_method, and read payment_method_save on the checkout session. A card saved with the number makes it the customer's saved number, and the cards saved with the number it replaces are removed. A card not confirmed in time is not saved. maxLength: 16. pattern: ^\+1[2-9][0-9]{2}[2-9][0-9]{6}$. */ "save_payment_method_phone"?: string; };
